"use strict";
const fs = require("node:fs");
const path = require("node:path");
const cp = require("node:child_process");
const crypto = require("node:crypto");
const root = __dirname;
const repo = "/Users/xu/project/worktrees/cew-fast-path";
const hash = (b) => crypto.createHash("sha256").update(b).digest("hex");
const config = 'model = "gpt-6.1-sol"\nmodel_reasoning_effort = "high"\napproval_policy = "never"\nsandbox_mode = "workspace-write"\nsuppress_unstable_features_warning = true\n';
const arms = [
  { cell: "gpt-cew", home: "cew-home", version: "main", sha: "e57aa53bb4b1ba8c065be5714c23e451bf6a6ad5" },
  { cell: "gpt-trim", home: "cew-trim", version: "previous-pr", sha: "704ef6fdb589637468985f835b0f50e456490d40" },
  { cell: "gpt-fixed", home: "cew-fixed", version: "optimized", sha: "6238192c244f7c719934c266ef8e3991a397ae78" },
];
for (const arm of arms) {
  const source = path.join(root, "sources", arm.version);
  fs.mkdirSync(source, { recursive: true });
  const archive = cp.execFileSync("git", ["archive", "--format=tar", arm.sha], { cwd: repo, maxBuffer: 64 * 1024 * 1024 });
  cp.execFileSync("tar", ["-xf", "-", "-C", source], { input: archive });
  fs.symlinkSync(path.join(repo, "node_modules"), path.join(source, "node_modules"));
  const home = path.join(root, "templates", arm.home);
  fs.mkdirSync(home, { recursive: true });
  const install = cp.spawnSync("/bin/bash", [path.join(source, "scripts/install.sh"), "--codex-only"],
    { cwd: source, encoding: "utf8", env: { ...process.env, HOME: home, CODEX_HOME: path.join(home, ".codex") } });
  fs.writeFileSync(path.join(root, `install-${arm.version}.log`), (install.stdout || "") + (install.stderr || ""));
  if (install.error || install.status !== 0) throw new Error(`Installer failed: ${arm.version}`);
  fs.writeFileSync(path.join(home, ".codex/config.toml"), config);
  fs.copyFileSync("/Users/xu/.codex/auth.json", path.join(home, ".codex/auth.json"));
  fs.chmodSync(path.join(home, ".codex/auth.json"), 0o600);
  arm.archive_sha256 = hash(archive);
  arm.config_sha256 = hash(config);
  arm.agents_sha256 = hash(fs.readFileSync(path.join(home, ".codex/AGENTS.md")));
  arm.policy_files = ["rules/common/testing.md", "skills/using-superpowers/SKILL.md", "skills/using-superpowers/references/fast-path.md"].flatMap((file) => {
    const installed = path.join(home, ".codex", file);
    if (!fs.existsSync(installed)) return [];
    if (!fs.readFileSync(installed).equals(fs.readFileSync(path.join(source, file)))) throw new Error("Installation mismatch: " + file);
    return [{ path: file, sha256: hash(fs.readFileSync(installed)) }];
  });
  console.log(JSON.stringify({ version: arm.version, installed: true, sha: arm.sha }));
}
if (new Set(arms.map((a) => a.agents_sha256)).size !== 1) throw new Error("AGENTS.md must remain exactly main");
if (new Set(arms.map((a) => a.config_sha256)).size !== 1) throw new Error("Execution configuration differs");
fs.writeFileSync(path.join(root, "protocol/installed-sources.json"), JSON.stringify(arms, null, 2));

