"use strict";
const fs = require("node:fs");
const path = require("node:path");
const cp = require("node:child_process");
const crypto = require("node:crypto");
const root = __dirname;
const source = "/Users/xu/project/worktrees/cew-fast-path";
const out = path.join(source, "docs/eval/data/optimized-2026-10-18");
const progress = JSON.parse(fs.readFileSync(path.join(root, "progress.json")));
if (progress.count !== 42) throw new Error("Require all 42 scheduled outcomes, including failures");
const experiment = JSON.parse(fs.readFileSync(path.join(root, "experiment.json")));
const analysis = JSON.parse(fs.readFileSync(path.join(root, "analysis.json")));
const hash = (bytes) => crypto.createHash("sha256").update(bytes).digest("hex");
const normalize = (value) => JSON.parse(JSON.stringify(value).replaceAll(`/private${root}`, "<BENCH_ROOT>").replaceAll(root, "<BENCH_ROOT>"));
const secrets = [];
function collectSecrets(value) {
  if (typeof value === "string" && value.length >= 20) secrets.push(value);
  else if (value && typeof value === "object") for (const v of Object.values(value)) collectSecrets(v);
}
collectSecrets(JSON.parse(fs.readFileSync(path.join(root, "templates/cew-home/.codex/auth.json"))));
for (const name of ["cew-home", "cew-trim", "cew-fixed"]) collectSecrets(JSON.parse(fs.readFileSync(path.join(root, "templates", name, ".codex/auth.json"))));
for (const receipt of progress.completed) {
  const trial = path.dirname(receipt.result_file).replace(/\/results\/.+$/, "");
  const home = { "gpt-cew": "cew-home", "gpt-trim": "cew-trim", "gpt-fixed": "cew-fixed" }[receipt.cell];
  collectSecrets(JSON.parse(fs.readFileSync(path.join(trial, "homes", home, ".codex/auth.json"))));
}
const oldSource = cp.execFileSync("git", ["show", "2296603:docs/eval/tools/run_trial.py"], { cwd: source, encoding: "utf8" });
for (const m of oldSource.matchAll(/["']([A-Za-z0-9_./:+-]{24,})["']/g)) {
  if (/token|key|bearer/i.test(oldSource.slice(Math.max(0, m.index - 80), m.index))) secrets.push(m[1]);
}
function save(name, data) {
  const text = typeof data === "string" ? data : JSON.stringify(normalize(data), null, 2) + "\n";
  if (secrets.some((secret) => text.includes(secret))) throw new Error(`Credential match in ${name}; refusing export`);
  fs.writeFileSync(path.join(out, name), text);
}
fs.mkdirSync(out, { recursive: true });
const runnerNow = hash(fs.readFileSync(path.join(source, "docs/eval/tools/run-trial.js")));
const manifestNow = hash(fs.readFileSync(path.join(root, "tasks.validated.json")));
if (runnerNow !== experiment.runner_sha256 || manifestNow !== experiment.manifest_sha256) throw new Error("Frozen inputs changed during experiment");
experiment.end_runner_sha256 = runnerNow;
experiment.end_manifest_sha256 = manifestNow;
experiment.predeclared_protocol = JSON.parse(fs.readFileSync(path.join(root, "protocol/protocol.json")));
experiment.installed_sources = JSON.parse(fs.readFileSync(path.join(root, "protocol/installed-sources.json")));
experiment.end_driver_sha256 = hash(fs.readFileSync(path.join(root, "run-final-benchmark.cjs")));
experiment.end_quality_protocol_sha256 = hash(fs.readFileSync(path.join(root, "protocol/frozen-quality-probes.cjs")));
if (experiment.end_driver_sha256 !== experiment.benchmark_driver_sha256 || experiment.end_quality_protocol_sha256 !== experiment.quality_protocol_sha256) throw new Error("Frozen protocol changed");
const sourceIntegrity = [];
for (const arm of experiment.installed_sources) {
  for (const policy of arm.policy_files) {
    const sourceBytes = fs.readFileSync(path.join(root, "sources", arm.version, policy.path));
    const templateBytes = fs.readFileSync(path.join(root, "templates", arm.home, ".codex", policy.path));
    if (hash(sourceBytes) !== policy.sha256 || hash(templateBytes) !== policy.sha256) throw new Error("Frozen source/template changed");
  }
  sourceIntegrity.push({ cell: arm.cell, sha: arm.sha, source_and_template_match: true });
}
experiment.source_integrity = sourceIntegrity;
experiment.benchmark_driver_source = fs.readFileSync(path.join(root, "run-final-benchmark.cjs"), "utf8");
experiment.setup_source = fs.readFileSync(path.join(root, "setup.cjs"), "utf8");
experiment.configs = ["cew-home", "cew-trim", "cew-fixed"].map((arm) => {
  const home = path.join(root, "templates", arm, ".codex");
  return { arm, config_sha256: hash(fs.readFileSync(path.join(home, "config.toml"))),
    agents_sha256: fs.existsSync(path.join(home, "AGENTS.md")) ? hash(fs.readFileSync(path.join(home, "AGENTS.md"))) : null };
});
experiment.config_public_fields = { model: "gpt-6.1-sol", model_reasoning_effort: "high", approval_policy: "never", sandbox_mode: "workspace-write", suppress_unstable_features_warning: true };
experiment.execution_override = "Every arm uses the same existing runner flag --dangerously-bypass-approvals-and-sandbox; isolation is a process convention, not an OS security boundary.";
const packageBaselines = new Map();
const packageChanges = [];
let baselineMatches = 0, finishedMatches = 0;
for (const receipt of progress.completed) {
  const result = JSON.parse(fs.readFileSync(receipt.result_file));
  const repo = result.repo;
  if (!packageBaselines.has(repo)) {
    const python = path.join(root, "venvs", repo, "bin/python");
    const freeze = cp.execFileSync(python, ["-m", "pip", "freeze"], { encoding: "utf8" }).trim();
    packageBaselines.set(repo, { repo, python_version: cp.execFileSync(python, ["-VV"], { encoding: "utf8" }).trim(),
      sha256: hash(freeze), packages: freeze.split("\n") });
  }
  const baseline = packageBaselines.get(repo);
  if (baseline.sha256 === receipt.packages_before_sha256) baselineMatches++;
  const trial = path.dirname(receipt.result_file).replace(/\/results\/.+$/, "");
  const freeze = cp.execFileSync(path.join(trial, "venvs", repo, "bin/python"), ["-m", "pip", "freeze"], { encoding: "utf8" }).trim();
  if (hash(freeze) === receipt.packages_after_sha256) finishedMatches++;
  if (receipt.packages_changed) {
    const after = freeze.split("\n");
    packageChanges.push({ task: receipt.task, cell: receipt.cell, run: receipt.repetition,
      added: after.filter((p) => !baseline.packages.includes(p)), removed: baseline.packages.filter((p) => !after.includes(p)) });
  }
}
experiment.environment_audit = { trials: progress.count, initial_snapshot_matches: baselineMatches, final_snapshot_matches: finishedMatches,
  package_baselines: [...packageBaselines.values()], package_changes: packageChanges };
save("experiment.json", experiment);
save("analysis.json", analysis);
const quality = JSON.parse(fs.readFileSync(path.join(root, "quality-probes.json")));
if (quality.results.filter((r) => r.cell).length !== 6) throw new Error("Require supplemental queries for all six numeric_range outcomes");
save("quality-probes.json", quality);
const i18n = JSON.parse(fs.readFileSync(path.join(root, "i18n-probes.json")));
if (i18n.results.length !== 12) throw new Error("Require supplemental translation checks for all twelve humanize artifacts");
if (hash(fs.readFileSync(path.join(root, "i18n-probes.cjs"))) !== i18n.amendment.controller_sha256) throw new Error("Translation check protocol changed");
save("i18n-probes.json", i18n);
const cost = JSON.parse(fs.readFileSync(path.join(root, "cost-probes.json")));
if (cost.results.filter((r) => r.cell).length !== 6) throw new Error("Require supplemental cost/sequence checks for all six numeric_range artifacts");
if (hash(fs.readFileSync(path.join(root, "cost-probes.cjs"))) !== cost.amendment.controller_sha256) throw new Error("Cost check protocol changed");
save("cost-probes.json", cost);
const fixtures = JSON.parse(fs.readFileSync(path.join(root, "tasks.validated.json"))).map((task) => {
  const repo = path.join(root, "repos", task.repo);
  const git = (...args) => cp.execFileSync("git", args, { cwd: repo, encoding: "utf8" });
  const targetPatch = git("diff", task.parent, task.commit, "--", ...task.test_files);
  const sourcePatch = git("diff", task.parent, task.commit, "--", ...task.source_files);
  return { id: task.id, repo: task.repo, commit: task.commit, original_commit: task.original_commit || task.commit,
    parent: task.parent, issue: task.issue, test_files: task.test_files, source_files: task.source_files,
    fixture_note: task.fixture_note || "Parent plus regression-test diff from the recorded replay commit.",
    validation: task.validation, test_patch: targetPatch, reference_source_patch: sourcePatch };
});
save("task-fixtures.json", fixtures);
const rows = progress.completed.map((receipt) => {
  if (!fs.existsSync(receipt.result_file)) throw new Error(`Missing graded result: ${receipt.task}/${receipt.cell}/${receipt.repetition}`);
  const result = JSON.parse(fs.readFileSync(receipt.result_file));
  const trial = path.dirname(receipt.result_file).replace(/\/results\/.+$/, "");
  const log = fs.readFileSync(path.join(path.dirname(receipt.result_file), "agent.log"), "utf8");
  const events = log.split("\n").flatMap((line) => { try { return [JSON.parse(line)]; } catch { return []; } });
  const homeName = { "gpt-trim": "cew-trim", "gpt-cew": "cew-home", "gpt-fixed": "cew-fixed" }[result.cell];
  const configHash = hash(fs.readFileSync(path.join(trial, "homes", homeName, ".codex/config.toml")));
  const configUnchanged = configHash === experiment.configs.find((c) => c.arm === homeName).config_sha256;
  const installed = experiment.installed_sources.find((arm) => arm.cell === result.cell);
  const trialPoliciesMatch = installed.policy_files.every((file) => hash(fs.readFileSync(path.join(trial, "homes", homeName, ".codex", file.path))) === file.sha256);
  if (!trialPoliciesMatch) throw new Error("Trial modified its own policy files");
  const templateConfig = fs.readFileSync(path.join(root, "templates", homeName, ".codex/config.toml"), "utf8").trim();
  const actualConfig = fs.readFileSync(path.join(trial, "homes", homeName, ".codex/config.toml"), "utf8").trim();
  const checkout = fs.realpathSync(path.join(trial, "runs", result.task, `${result.cell}-r${result.run}`));
  const expectedTrustConfig = templateConfig + "\n\n[projects." + JSON.stringify(checkout) + "]\ntrust_level = \"trusted\"";
  const trustOnly = actualConfig === expectedTrustConfig;
  const commands = events.filter((e) => e.type === "item.completed" && e.item?.type === "command_execution")
    .map((e) => ({ command: e.item.command, exit_code: e.item.exit_code }));
  const reports = ["base-full", "target", "after-full"].map((name) => {
    const file = path.join(path.dirname(receipt.result_file), name + ".xml");
    return { name, sha256: hash(fs.readFileSync(file)) };
  });
  const testOrRunnerFiles = result.diff.files.filter((file) => /(?:^|\/)(?:tests?|conftest\.py|pytest\.ini|tox\.ini|setup\.cfg|pyproject\.toml|Makefile)(?:\/|$)|(?:^|\/)test[^/]*\.py$/.test(file));
  const supplemental = quality.results.find((q) => q.cell === result.cell && q.run === result.run);
  const probeApplies = result.task === "more-itertools-1247";
  if (probeApplies && !supplemental) throw new Error("Missing predeclared supplemental grading");
  const costCheck = probeApplies ? cost.results.find((r) => r.cell === result.cell && r.run === result.run) : null;
  const translations = i18n.results.find((r) => r.task === result.task && r.cell === result.cell && r.run === result.run);
  const allChecksPassed = result.resolved && (!probeApplies || supplemental.cases.every((r) => r.passed) && costCheck.cases.every((r) => r.passed)) && (!translations || translations.passed);
  const originalPatch = fs.readFileSync(path.join(trial, "change.patch"), "utf8");
  if (hash(originalPatch) !== receipt.patch_sha256) throw new Error("Original patch receipt mismatch");
  const replayPatch = cp.execFileSync("git", ["diff", "--binary", "HEAD", "--"], { cwd: checkout, encoding: "utf8", maxBuffer: 16 * 1024 * 1024 });
  if (originalPatch.trim() !== replayPatch.trim()) throw new Error("Replay patch differs beyond trailing whitespace");
  const replayCheck = cp.spawnSync("git", ["apply", "--check", "--reverse", "-"], { cwd: checkout, input: replayPatch, encoding: "utf8" });
  if (replayCheck.status !== 0) throw new Error(`Replay patch cannot reverse-apply: ${result.task}/${result.cell}/${result.run}: ${replayCheck.stderr}`);
  const originalCheck = cp.spawnSync("git", ["apply", "--check", "--reverse", "-"], { cwd: checkout, input: originalPatch, encoding: "utf8" });
  return normalize({ ...result, receipt, commands, reports, config_sha256: configHash, config_unchanged: configUnchanged,
    installed_policy_matches: trialPoliciesMatch,
    test_or_runner_files_changed: testOrRunnerFiles,
    test_case_count_unchanged: result.base_full.passed + result.base_full.failed + result.base_full.skipped === result.after_full.passed + result.after_full.failed + result.after_full.skipped,
    skip_delta: result.after_full.skipped - result.base_full.skipped,
    additional_numeric_quality: costCheck,
    additional_translation_quality: translations || null,
